const readline = require("readline");

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

rl.on("line", (line) => {
  console.log(getResult(line));
});

function getResult(s) {
  // 不区分大小写
  s = s.toLowerCase();

  // 统计每个字母出现的次数
  const count = {};

  // 去除字符串中的非字母
  const letters = [];

  for (let c of s) {
    if (c >= "a" && c <= "z") {
      count[c] = (count[c] ?? 0) + 1;
      letters.push(c);
    }
  }

  // 加空格是为了避免后续的收尾操作，如果有疑问可以移除下面加空格操作
  s = letters.join("") + " ";

  // 记录连续字母和非连续字母
  const ans = [];

  // 上一个位置的字母
  let pre = s[0];
  // 该字母连续次数记为1
  let repeat = 1;
  // 后续该字母还有count[pre]-=1个
  count[pre]--;

  for (let i = 1; i < s.length; i++) {
    // 当前位置的字母
    const cur = s[i];
    // 后续该字母还有count[cur]-=1个
    count[cur]--;

    if (cur == pre) {
      // 如果当前位置和上一个位置的字母相同，则产生连续
      // 连续次数+1
      repeat++;
    } else {
      // 如果当前位置和上一个位置的字母不同，则连续打断
      // 如果pre字母连续次数>1，则是真连续，那么就是pre+repeat,否则就是假连续,是pre+count[pre]
      ans.push([pre, repeat > 1 ? repeat : count[pre]]);
      // 更新pre为cur
      pre = cur;
      // 更新pre连续次数为1
      repeat = 1;
    }
  }

  // 字母和紧随的数字作为一组进行排序，数字大的在前，数字相同的，则按字母进行排序，字母小的在前
  return ans
    .sort((a, b) =>
      a[1] != b[1] ? b[1] - a[1] : a[0].charCodeAt() - b[0].charCodeAt()
    )
    .map(([letter, num]) => letter + num)
    .join("");
}

