#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_SIZE 201

typedef struct {
    char letter;
    int num;
} Letter;

int cmp(const void *a, const void *b) {
    Letter *A = (Letter *) a;
    Letter *B = (Letter *) b;

    return A->num != B->num ? B->num - A->num : A->letter - B->letter;
}

int main() {
    char s[MAX_SIZE];
    gets(s);

    unsigned long long len = strlen(s);

    // 记录转小写，去除非字母后的s字符串
    char ss[MAX_SIZE];
    int ss_size = 0;

    // 统计每个字母出现的次数
    int count[128] = {0};
    for (int i = 0; i < len; i++) {
        char c = s[i];
        if (c >= 'a' && c <= 'z') {
            count[c]++;
            ss[ss_size++] = c;
        } else if (c >= 'A' && c <= 'Z') {
            count[c + 32]++;
            ss[ss_size++] = (char) (c + 32);
        }
    }

    // 记录连续字母和非连续字母
    Letter res[MAX_SIZE];
    int res_size = 0;

    // 上一个位置的字母
    char pre = ss[0];
    // 该字母连续次数记为1
    int repeat = 1;
    // 后续该字母还有count[pre]-=1个
    count[pre]--;

    for (int i = 1; i <= ss_size; i++) {
        // 当前位置的字母
        char cur = ss[i];
        // 后续该字母还有count[cur]-=1个
        count[cur]--;

        if (cur == pre) {
            // 如果当前位置和上一个位置的字母相同，则产生连续
            // 连续次数+1
            repeat++;
        } else {
            // 如果当前位置和上一个位置的字母不同，则连续打断
            // 如果pre字母连续次数>1，则是真连续，那么就是pre+repeat,否则就是假连续,是pre+count[pre]
            res[res_size].num = repeat > 1 ? repeat : count[pre];
            res[res_size].letter = pre;
            res_size++;

            // 更新pre为cur
            pre = cur;
            // 更新pre连续次数为1
            repeat = 1;
        }
    }

    // 字母和紧随的数字作为一组进行排序，数字大的在前，数字相同的，则按字母进行排序，字母小的在前
    qsort(res, res_size, sizeof(Letter), cmp);

    char ans[MAX_SIZE] = {'\0'};
    for (int i = 0; i < res_size; i++) {
        char letter[2];
        sprintf(letter, "%c", res[i].letter);

        char num[10];
        sprintf(num, "%d", res[i].num);

        strcat(ans, letter);
        strcat(ans, num);
    }

    puts(ans);

    return 0;
}
